INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'amateur', 'n./adj.', '/ˈæmətə(r)/', '业余爱好者;业余的', 'Even an amateur can write a simple poem with a little practice.', '稍加练习,即便业余爱好者也能写出一首简单的诗。', 'Poems', 1, 0, 'senior', 'wordlist', 'elective3', 'U5', 'an amateur poet', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'await', 'v.', '/əˈweɪt/', '等候;期待;将发生在', 'In the Tang poem, a faithful wife stands on the hill to await her husband.', '在那首唐诗里,忠贞的妻子立于山上等候丈夫。', 'Poems', 2, 0, 'senior', 'wordlist', 'elective3', 'U5', 'await her husband', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'barren', 'adj.', '/ˈbærən/', '贫瘠的;不结果实的', 'Without dreams, the poet says, life becomes a barren field frozen with snow.', '诗人说,没有梦想,生活就成了一片被白雪覆盖的贫瘠田野。', 'Poems', 3, 0, 'senior', 'wordlist', 'elective3', 'U5', 'a barren field', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'cherry', 'n.', '/ˈtʃeri/', '樱桃;樱桃树;樱桃色', 'Many haiku describe the cherry blossom falling softly in spring.', '许多俳句描写春天里樱花轻柔飘落的情景。', 'Poems', 4, 0, 'senior', 'wordlist', 'elective3', 'U5', 'cherry blossom', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'cinquain', 'n.', '/ˈsɪŋkeɪn/', '五行诗', 'A cinquain is a short poem made up of five lines.', '五行诗是一种由五行组成的短诗。', 'Poems', 5, 0, 'senior', 'wordlist', 'elective3', 'U5', 'write a cinquain', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'civilian', 'n.', '/səˈvɪliən/', '平民;老百姓', 'In Shakespeare''s plays, characters from civilians to kings all speak in blank verse.', '在莎士比亚的戏剧里,从平民到国王的角色都用无韵诗说话。', 'Poems', 6, 0, 'senior', 'wordlist', 'elective3', 'U5', 'from civilian to king', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'clover', 'n.', '/ˈkləʊvə(r)/', '三叶草', 'The list poem mentions soft grass and a field of clover by the river.', '那首列举诗提到了河边柔软的青草和一片三叶草。', 'Poems', 7, 0, 'senior', 'wordlist', 'elective3', 'U5', 'a field of clover', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'complicated', 'adj.', '/ˈkɒmplɪkeɪtɪd/', '复杂的;难懂的', 'Over time, simple folk songs became more complicated and more polished poems.', '随着时间推移,简单的民歌变成了更复杂、更精致的诗作。', 'Poems', 8, 0, 'senior', 'wordlist', 'elective3', 'U5', 'become more complicated', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'comprehension', 'n.', '/ˌkɒmprɪˈhenʃn/', '理解力;领悟力;理解练习', 'Good poetry comprehension means imagining the picture the poem is painting.', '良好的诗歌理解力意味着在脑海中想象诗歌所描绘的画面。', 'Poems', 9, 0, 'senior', 'wordlist', 'elective3', 'U5', 'poetry comprehension', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'core', 'n.', '/kɔː(r)/', '核心;精髓;(水果的)核儿', 'Literary criticism tries to get to the core of the text and find its message.', '文学批评力图触及文本的核心,找出它要传达的信息。', 'Poems', 10, 0, 'senior', 'wordlist', 'elective3', 'U5', 'the core of the text', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'correspond', 'v.', '/ˌkɒrəˈspɒnd/', '相一致;符合;通信', 'The two poets began to correspond after one admired the other''s verse.', '其中一位欣赏了另一位的诗作后,两位诗人开始通信。', 'Poems', 11, 0, 'senior', 'wordlist', 'elective3', 'U5', 'correspond with each other', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'correspondence', 'n.', '/ˌkɒrəˈspɒndəns/', '来往信件;通信联系', 'Their personal correspondence helped sow the seeds of love between them.', '他们之间的私人通信帮助播下了爱情的种子。', 'Poems', 12, 0, 'senior', 'wordlist', 'elective3', 'U5', 'personal correspondence', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'dawn', 'n.', '/dɔːn/', '黎明;开端;萌芽', 'The poem paints a quiet picture of dew on the grass at dawn.', '这首诗描绘了黎明时分草上露珠的宁静画面。', 'Poems', 13, 0, 'senior', 'wordlist', 'elective3', 'U5', 'at dawn', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'deadline', 'n.', '/ˈdedlaɪn/', '最后期限;截止日期', 'Nora asked her teacher when the deadline for the poetry contest was.', '诺拉问老师诗歌比赛的截止日期是什么时候。', 'Poems', 14, 0, 'senior', 'wordlist', 'elective3', 'U5', 'the deadline for the contest', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'delicate', 'adj.', '/ˈdelɪkət/', '精美的;精致的;脆弱的', 'The haiku shows a moment in the life of a delicate butterfly.', '那首俳句展现了一只脆弱蝴蝶生命中的一个瞬间。', 'Poems', 15, 0, 'senior', 'wordlist', 'elective3', 'U5', 'a delicate butterfly', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'dewdrop', 'n.', '/ˈdjuːdrɒp/', '露珠;水珠', 'A single dewdrop on a leaf can be the subject of a whole haiku.', '一片叶子上的一颗露珠就能成为一首俳句的主题。', 'Poems', 16, 0, 'senior', 'wordlist', 'elective3', 'U5', 'a tiny dewdrop', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'diamond', 'n.', '/ˈdaɪəmənd/', '钻石;金刚石;菱形', 'A cinquain printed on the page often looks like a small diamond shape.', '印在纸上的五行诗常常看起来像一个小菱形。', 'Poems', 17, 0, 'senior', 'wordlist', 'elective3', 'U5', 'a diamond shape', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'dominant', 'adj.', '/ˈdɒmɪnənt/', '首要的;占支配地位的;显著的', 'Her father was a dominant and selfish man who refused to let her go.', '她的父亲是个专横自私的人,不肯放她走。', 'Poems', 18, 0, 'senior', 'wordlist', 'elective3', 'U5', 'a dominant figure', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'drama', 'n.', '/ˈdrɑːmə/', '戏;剧;戏剧艺术', 'Blank verse is common in drama, especially in the plays of Shakespeare.', '无韵诗在戏剧中很常见,尤其是在莎士比亚的剧作里。', 'Poems', 19, 0, 'senior', 'wordlist', 'elective3', 'U5', 'poetic drama', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'era', 'n.', '/ˈɪərə/', '时代;年代;纪元', 'The Brownings were one of the most romantic literary couples of the Victorian era.', '勃朗宁夫妇是维多利亚时代最浪漫的文学伉俪之一。', 'Poems', 20, 0, 'senior', 'wordlist', 'elective3', 'U5', 'the Victorian era', '美音 /ˈerə/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'folk', 'adj./n.', '/fəʊk/', '民间的;民俗的;人们', 'Poetry probably had its origins in traditional folk music long ago.', '诗歌很可能很久以前起源于传统的民间音乐。', 'Poems', 21, 0, 'senior', 'wordlist', 'elective3', 'U5', 'folk music', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'format', 'n.', '/ˈfɔːmæt/', '格式;总体安排;版式', 'A haiku has a format of three lines containing five, seven and five syllables.', '俳句有三行的格式,分别含五、七、五个音节。', 'Poems', 22, 0, 'senior', 'wordlist', 'elective3', 'U5', 'a simple format', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'grief', 'n.', '/ɡriːf/', '悲伤;悲痛;伤心事', 'The poem moves between green pleasure and grey grief like the changing weather.', '这首诗在绿色的欢乐与灰色的悲伤之间游移,如同变幻的天气。', 'Poems', 23, 0, 'senior', 'wordlist', 'elective3', 'U5', 'joy and grief', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'haiku', 'n.', '/ˈhaɪkuː/', '俳句', 'A haiku is a Japanese form of poetry that consists of seventeen syllables.', '俳句是一种由十七个音节组成的日本诗体。', 'Poems', 24, 0, 'senior', 'wordlist', 'elective3', 'U5', 'a Japanese haiku', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'imagery', 'n.', '/ˈɪmɪdʒəri/', '形象的描述;意象', 'Poets use vivid imagery to paint pictures in the reader''s mind.', '诗人用生动的意象在读者心中描绘画面。', 'Poems', 25, 0, 'senior', 'wordlist', 'elective3', 'U5', 'vivid imagery', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'innocence', 'n.', '/ˈɪnəsns/', '天真;单纯;无罪', 'Readers of the collection can feel the warmth of love and the innocence of childhood.', '这部诗集的读者能感受到爱的温暖和童年的天真。', 'Poems', 26, 0, 'senior', 'wordlist', 'elective3', 'U5', 'the innocence of childhood', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'innocent', 'adj.', '/ˈɪnəsnt/', '天真无邪的;无辜的', 'The nursery rhyme is written from the innocent point of view of a small child.', '这首童谣是从一个小孩天真无邪的视角写成的。', 'Poems', 27, 0, 'senior', 'wordlist', 'elective3', 'U5', 'an innocent child', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'lawn', 'n.', '/lɔːn/', '草坪;草地', 'In the poem, the morning light spreads softly across the green lawn.', '在诗中,晨光柔和地洒满绿色的草坪。', 'Poems', 28, 0, 'senior', 'wordlist', 'elective3', 'U5', 'on the lawn', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'literary', 'adj.', '/ˈlɪtərəri/', '文学的;爱好文学的', 'If you study English literary history, you will meet the names of many great poets.', '如果你学习英语文学史,就会遇到许多伟大诗人的名字。', 'Poems', 29, 0, 'senior', 'wordlist', 'elective3', 'U5', 'literary criticism', '美音 /ˈlɪtəreri/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'mockingbird', 'n.', '/ˈmɒkɪŋbɜːd/', '嘲鸫(能模仿别种鸟鸣的鸣禽)', 'The word ''heard'' in the verse rhymes neatly with ''bird'' and ''mockingbird''.', '诗句中的 heard 与 bird 和 mockingbird 押韵工整。', 'Poems', 30, 0, 'senior', 'wordlist', 'elective3', 'U5', 'a singing mockingbird', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'mood', 'n.', '/muːd/', '情绪;心情;语气', 'A cinquain can convey a strong picture or a certain mood in just a few words.', '五行诗只用寥寥几个词就能传达一幅鲜明的画面或某种情绪。', 'Poems', 31, 0, 'senior', 'wordlist', 'elective3', 'U5', 'create a mood', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'nursery', 'n./adj.', '/ˈnɜːsəri/', '托儿所;育儿的', 'A nursery rhyme often uses simple rhymes and repetition that children enjoy.', '童谣常用孩子们喜爱的简单押韵和重复。', 'Poems', 32, 0, 'senior', 'wordlist', 'elective3', 'U5', 'a nursery rhyme', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'polish', 'v./n.', '/ˈpɒlɪʃ/', '修改;润色;抛光', 'Nora said she still needed time to polish her writing before the contest.', '诺拉说她在比赛前还需要时间来润色自己的作品。', 'Poems', 33, 0, 'senior', 'wordlist', 'elective3', 'U5', 'polish her writing', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'prejudice', 'n.', '/ˈpredʒudɪs/', '偏见;成见', 'His poem dreams of a world free of inequality and racial prejudice.', '他的诗梦想着一个没有不平等和种族偏见的世界。', 'Poems', 34, 0, 'senior', 'wordlist', 'elective3', 'U5', 'racial prejudice', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'prose', 'n.', '/prəʊz/', '散文', 'Students are asked to recite ancient poems and works of prose from their course.', '学生们被要求背诵课程中学过的古诗和散文作品。', 'Poems', 35, 0, 'senior', 'wordlist', 'elective3', 'U5', 'poems and prose', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'racial', 'adj.', '/ˈreɪʃl/', '种族的;人种的', 'Langston Hughes''s poems often call for racial equality and shared joy.', '兰斯顿·休斯的诗常常呼吁种族平等和共享的快乐。', 'Poems', 36, 0, 'senior', 'wordlist', 'elective3', 'U5', 'racial equality', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'recite', 'v.', '/rɪˈsaɪt/', '背诵;吟诵;列举', 'Poems are best understood when you recite them aloud and with feeling.', '当你带着感情大声吟诵时,诗歌最能被理解。', 'Poems', 37, 0, 'senior', 'wordlist', 'elective3', 'U5', 'recite a poem', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'respective', 'adj.', '/rɪˈspektɪv/', '分别的;各自的', 'The three lines of a haiku have five, seven and five syllables respective to their order.', '俳句的三行按各自的顺序分别有五、七、五个音节。', 'Poems', 38, 0, 'senior', 'wordlist', 'elective3', 'U5', 'their respective lines', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'respectively', 'adv.', '/rɪˈspektɪvli/', '分别;各自;依次为', 'The three lines contain five, seven and five syllables respectively.', '这三行依次分别含有五、七、五个音节。', 'Poems', 39, 0, 'senior', 'wordlist', 'elective3', 'U5', 'five, seven and five respectively', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'revolve', 'v.', '/rɪˈvɒlv/', '旋转;环绕;转动', 'Day by day upon the mountain top, the wind and rain revolve around the stone.', '日复一日在山顶上,风和雨环绕着那块石头旋转。', 'Poems', 40, 0, 'senior', 'wordlist', 'elective3', 'U5', 'wind and rain revolve', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'rhyme', 'n./v.', '/raɪm/', '押韵;押韵词;押韵的短诗', 'In the poem ''Dream'', the words ''die'' and ''fly'' rhyme and sound pleasing.', '在《梦想》一诗中,die 和 fly 押韵,读来悦耳。', 'Poems', 41, 0, 'senior', 'wordlist', 'elective3', 'U5', 'words that rhyme', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'rhythm', 'n.', '/ˈrɪðəm/', '节奏;韵律;规律', 'The sounds and rhythm of a poem give it a musical quality.', '诗歌的声音和节奏赋予它一种音乐般的特质。', 'Poems', 42, 0, 'senior', 'wordlist', 'elective3', 'U5', 'the rhythm of the poem', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'seed', 'n.', '/siːd/', '种子;起源;萌芽', 'Their letters helped to sow the seeds of love between the two poets.', '他们的信件帮助在两位诗人之间播下了爱情的种子。', 'Poems', 43, 0, 'senior', 'wordlist', 'elective3', 'U5', 'sow the seeds', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'sonnet', 'n.', '/ˈsɒnɪt/', '十四行诗', 'A sonnet is a poem of fourteen lines and is often about love.', '十四行诗是一首十四行的诗,常常以爱情为主题。', 'Poems', 44, 0, 'senior', 'wordlist', 'elective3', 'U5', 'write a sonnet', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'sorrow', 'n.', '/ˈsɒrəʊ/', '悲伤;悲痛;伤心事', 'The poet wrote about the joys and sorrows of everyday life.', '诗人书写了日常生活中的欢乐与悲伤。', 'Poems', 45, 0, 'senior', 'wordlist', 'elective3', 'U5', 'the joys and sorrows of life', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'sow', 'v.', '/səʊ/', '播种;种', 'Ancient folk songs often sang about hunting animals or sowing crops.', '古老的民歌常常歌唱狩猎动物或播种庄稼。', 'Poems', 46, 0, 'senior', 'wordlist', 'elective3', 'U5', 'sow crops', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'syllable', 'n.', '/ˈsɪləbl/', '音节', 'A haiku consists of exactly seventeen syllables in three short lines.', '俳句恰好由三短行中的十七个音节组成。', 'Poems', 47, 0, 'senior', 'wordlist', 'elective3', 'U5', 'seventeen syllables', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'sympathetic', 'adj.', '/ˌsɪmpəˈθetɪk/', '同情的;有同情心的;赞同的', 'The poet Tagore shows a sympathetic understanding of children''s feelings.', '诗人泰戈尔表现出对儿童情感富有同情心的理解。', 'Poems', 48, 0, 'senior', 'wordlist', 'elective3', 'U5', 'a sympathetic understanding', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'tease', 'v.', '/tiːz/', '取笑;揶揄;逗弄', 'In the cinquain, the brother is teasing, shouting and laughing all at once.', '在那首五行诗里,哥哥同时在逗弄、喊叫和大笑。', 'Poems', 49, 0, 'senior', 'wordlist', 'elective3', 'U5', 'teasing and laughing', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'utter', 'v./adj.', '/ˈʌtə(r)/', '说;出声;完全的', 'Should the traveller return, this stone would utter speech, the Tang poem says.', '那首唐诗说,倘若行人归来,这块石头便会开口说话。', 'Poems', 50, 0, 'senior', 'wordlist', 'elective3', 'U5', 'utter speech', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'variation', 'n.', '/ˌveəriˈeɪʃn/', '变化;变体;变奏曲', 'Over the years, different variations of these old songs and poems developed.', '多年间,这些古老歌谣和诗作发展出了不同的变体。', 'Poems', 51, 0, 'senior', 'wordlist', 'elective3', 'U5', 'different variations', '美音 /ˌveriˈeɪʃn/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'verse', 'n.', '/vɜːs/', '诗;韵文;诗节', 'Free verse is an open form of poetry that follows no regular rhythm.', '自由诗是一种不遵循固定节奏的开放诗体。', 'Poems', 52, 0, 'senior', 'wordlist', 'elective3', 'U5', 'free verse', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'version', 'n.', '/ˈvɜːʃn/', '版本;(不同的)说法', 'The English version of the book contains nearly fifty short poems.', '这本书的英文版收录了近五十首短诗。', 'Poems', 53, 0, 'senior', 'wordlist', 'elective3', 'U5', 'the English version', NULL);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e3u5.01', '①关系代词 who/whom/which/that/whose', 'A2', 12, '选择性必修三 U5 — 先行词指人用 who/whom、指物用 which/that;从句缺主语或宾语时用关系代词;whose 表所属(后接名词)。', 1, 'elective3', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e3u5.02', '②关系副词 where/when/why 与「介词+which/whom」', 'A2', 12, '选择性必修三 U5 — 从句不缺主宾、只缺状语时:地点用 where、时间用 when、原因用 why;更正式或介词提前时用「介词+which/whom」(in which / on which / for which / to whom)。', 2, 'elective3', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e3u5.03', '③限制性 vs 非限制性 · which 指代整句 · as 引导', 'A2', 12, '选择性必修三 U5 — 非限制性(有逗号)指人用 who、指物用 which,绝不用 that;which 可指代前面整个句子;as 引导非限制性从句表示「正如」(as is known)。', 3, 'elective3', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.01'), 'The poet ____ wrote this sonnet lived during the Victorian era.', 'who', 'which', 'whose', 'where', 'A', '先行词 poet 指人、从句缺主语 → who。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.01'), 'Tagore is the writer ____ won the Nobel Prize in Literature.', 'which', 'who', 'whom', 'when', 'B', '先行词 writer 指人、从句缺主语 → who(whom 只作宾语)。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.01'), 'The haiku ____ describes a falling blossom is very famous.', 'who', 'whose', 'which', 'where', 'C', '先行词 haiku 指物、从句缺主语 → which。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.01'), 'This is the nursery rhyme ____ my mother used to sing to me.', 'who', 'whose', 'why', 'that', 'D', '先行词 rhyme 指物、从句缺宾语(sing ___)→ that。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.01'), 'Langston Hughes was a poet ____ poems tell the story of black people.', 'whose', 'who', 'which', 'where', 'A', '先行词 poet,后接名词 poems 表所属 → whose。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.01'), 'The cinquain ____ you wrote in class paints a clear picture.', 'who', 'that', 'whose', 'when', 'B', '先行词 cinquain 指物、从句缺宾语(wrote ___)→ that。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.01'), 'She is the only student ____ has memorised sixty ancient poems.', 'which', 'whose', 'that', 'where', 'C', '先行词被 only 修饰、指人作主语 → that(此时优先 that)。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.01'), 'Robert Browning was the man ____ Elizabeth finally married in secret.', 'which', 'whose', 'when', 'whom', 'D', '先行词 man 指人、从句缺宾语(married ___)→ whom(亦可 who/that,此处只 whom 成立)。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.01'), 'A sonnet is a poem ____ contains exactly fourteen lines.', 'that', 'who', 'whose', 'why', 'A', '先行词 poem 指物、从句缺主语 → that。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.01'), 'The amateur ____ first read the poem aloud felt rather nervous.', 'which', 'who', 'whose', 'where', 'B', '先行词 amateur 指人、从句缺主语 → who。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.01'), 'I still keep the old book ____ cover has almost fallen apart.', 'who', 'which', 'whose', 'when', 'C', '先行词 book,后接名词 cover 表所属 → whose。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.01'), 'The butterfly ____ the haiku describes lands on a single branch.', 'who', 'whose', 'where', 'that', 'D', '先行词 butterfly 指物、从句缺宾语(describes ___)→ that。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.01'), 'The Crescent Moon is the collection ____ made Tagore loved in China.', 'that', 'who', 'whose', 'why', 'A', '先行词 collection 指物、从句缺主语 → that。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.01'), 'He is a teacher ____ encourages every student to write a poem.', 'which', 'who', 'whose', 'when', 'B', '先行词 teacher 指人、从句缺主语 → who。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.01'), 'The poems ____ we recited this morning were full of vivid imagery.', 'who', 'whose', 'that', 'where', 'C', '先行词 poems 指物、从句缺宾语(recited ___)→ that。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.01'), 'Elizabeth was a poet ____ verse won great success in 1844.', 'who', 'which', 'why', 'whose', 'D', '先行词 poet,后接名词 verse 表所属 → whose。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.01'), 'The traveller ____ the lonely wife awaits never returns home.', 'whom', 'which', 'whose', 'when', 'A', '先行词 traveller 指人、从句缺宾语(awaits ___)→ whom。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.01'), 'A limerick is a short poem ____ is usually silly and funny.', 'who', 'that', 'whose', 'where', 'B', '先行词 poem 指物、从句缺主语 → that。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.01'), 'The children ____ love this rhyme often repeat it again and again.', 'which', 'whose', 'who', 'why', 'C', '先行词 children 指人、从句缺主语 → who。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.01'), 'This is the very poem ____ first made me fall in love with verse.', 'who', 'whose', 'when', 'that', 'D', '先行词被 very 修饰、指物作主语 → that(此时优先 that)。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.02'), 'That is the classroom ____ our poetry contest was held last week.', 'where', 'which', 'who', 'whose', 'A', '先行词 classroom 表地点、从句完整(只缺地点状语)→ where。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.02'), '1844 was the year ____ Elizabeth''s Poems brought her great success.', 'which', 'when', 'where', 'whose', 'B', '先行词 year 表时间、从句完整 → when。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.02'), 'Nobody knows the reason ____ the wind comes from somewhere far away.', 'which', 'where', 'why', 'whose', 'C', '先行词 reason、从句缺原因状语 → why。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.02'), 'Italy was the country ____ the Brownings spent the rest of their lives.', 'which', 'when', 'whose', 'where', 'D', '先行词 country 表地点、从句完整 → where。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.02'), 'I will never forget the day ____ I recited my first poem on stage.', 'when', 'which', 'where', 'whose', 'A', '先行词 day 表时间、从句完整 → when。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.02'), 'The library is the place ____ I quietly read poetry every afternoon.', 'which', 'where', 'when', 'whose', 'B', '先行词 place 表地点、从句完整 → where。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.02'), 'That is the manner in ____ a good poem should be read aloud.', 'where', 'that', 'which', 'whose', 'C', '介词 in 提前,后只能用 which → in which。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.02'), 'Spring is the season ____ cherry blossoms inspire countless haiku.', 'which', 'where', 'whose', 'when', 'D', '先行词 season 表时间、从句完整 → when。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.02'), 'There must be a reason ____ this simple rhyme has lasted so long.', 'why', 'which', 'where', 'whose', 'A', '先行词 reason、从句缺原因状语 → why。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.02'), 'Sonnets from the Portuguese is the book to ____ she owed her fame.', 'where', 'which', 'that', 'whose', 'B', '介词 to 提前、先行词指物 → to which。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.02'), 'This is the small room ____ the young poet wrote most of her verse.', 'which', 'when', 'where', 'whose', 'C', '先行词 room 表地点、从句完整 → where。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.02'), 'He is the poet to ____ this whole collection of poems is dedicated.', 'which', 'where', 'whose', 'whom', 'D', '介词 to 提前、先行词指人 → to whom。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.02'), 'That was the moment ____ the whole audience suddenly fell silent.', 'when', 'which', 'where', 'whose', 'A', '先行词 moment 表时间、从句完整 → when。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.02'), 'Tell me the reason ____ free verse follows no regular rhythm at all.', 'which', 'why', 'where', 'whose', 'B', '先行词 reason、从句缺原因状语 → why。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.02'), 'The branch on ____ the fallen blossom rests is painted in the haiku.', 'where', 'that', 'which', 'whose', 'C', '介词 on 提前、先行词指物 → on which。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.02'), 'The hill ____ the faithful wife stands has turned her into stone.', 'which', 'when', 'whose', 'where', 'D', '先行词 hill 表地点、从句完整 → where。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.02'), 'Autumn is the time of year ____ we hold our school poetry festival.', 'when', 'which', 'where', 'whose', 'A', '先行词 time of year 表时间、从句完整 → when。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.02'), 'Calligraphy is the art form by ____ the poet''s mood is also revealed.', 'where', 'which', 'that', 'whose', 'B', '介词 by 提前、先行词指物 → by which。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.02'), 'A free verse poem is one in ____ the poet has complete creative control.', 'where', 'that', 'which', 'whose', 'C', '介词 in 提前、先行词指物 → in which。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.02'), 'I cannot explain the reason ____ this poem always moves me to tears.', 'which', 'where', 'whose', 'why', 'D', '先行词 reason、从句缺原因状语 → why。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.03'), 'Bai Juyi, ____ lived in the mid-Tang Dynasty, is one of China''s greatest poets.', 'who', 'that', 'which', 'whom', 'A', '非限制性(逗号)、指人作主语 → who(非限制性绝不用 that)。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.03'), 'The haiku, ____ was translated from Japanese, shows a delicate butterfly.', 'that', 'which', 'who', 'where', 'B', '非限制性(逗号)、指物 → which(绝不用 that)。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.03'), 'The poem rhymes perfectly, ____ makes it very pleasing to read aloud.', 'that', 'what', 'which', 'where', 'C', '非限制性中 which 指代前面整个句子 → which。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.03'), 'Tagore, ____ poems Chinese readers love, wrote The Crescent Moon.', 'that', 'which', 'who', 'whose', 'D', '非限制性、后接名词 poems 表所属 → whose。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.03'), 'She finished the whole collection in a week, ____ surprised her teacher.', 'which', 'that', 'what', 'where', 'A', '非限制性中 which 指代前面整件事 → which。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.03'), 'Robert Browning, ____ Elizabeth admired deeply, became her husband.', 'that', 'whom', 'which', 'where', 'B', '非限制性、指人作宾语 → whom(绝不用 that)。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.03'), '____ is well known, blank verse has no rhyme but a natural rhythm.', 'Which', 'That', 'As', 'What', 'C', 'as 引导非限制性从句,可置于句首表「正如」→ As is well known。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.03'), 'The Brownings moved to Italy, ____ is famous for its long literary history.', 'that', 'where', 'what', 'which', 'D', '非限制性、指物(Italy)作主语 → which(此处不缺地点状语,故非 where)。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.03'), 'Langston Hughes, ____ wrote ''Dream'', spoke up for racial equality.', 'who', 'that', 'which', 'whom', 'A', '非限制性、指人作主语 → who。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.03'), 'He recited the sonnet beautifully, ____ won him the first prize.', 'that', 'which', 'what', 'where', 'B', '非限制性中 which 指代前面整个句子 → which。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.03'), 'The nursery rhyme, ____ rhythm is simple, is loved by little children.', 'that', 'which', 'whose', 'who', 'C', '非限制性、后接名词 rhythm 表所属 → whose。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.03'), '____ often happens in haiku, a single image carries the whole feeling.', 'Which', 'That', 'What', 'As', 'D', 'as 引导非限制性从句表「正如」,常置句首 → As often happens。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.03'), 'Elizabeth''s father, ____ was a dominant man, refused to let her go.', 'who', 'that', 'which', 'whom', 'A', '非限制性、指人作主语 → who。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.03'), 'The poem ends with a question, ____ leaves the reader thinking deeply.', 'that', 'which', 'what', 'where', 'B', '非限制性中 which 指代前面整件事 → which。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.03'), 'Swinburne, ____ poem ''A Match'' is short, compares love to a rose.', 'that', 'which', 'whose', 'who', 'C', '非限制性、后接名词 poem 表所属 → whose。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.03'), 'The two poets wrote each other many letters, ____ sowed the seeds of love.', 'that', 'what', 'where', 'which', 'D', '非限制性中 which 指代前面整件事 → which。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.03'), 'Wang Jian, ____ verse tells of a waiting wife, lived in the Tang Dynasty.', 'whose', 'that', 'which', 'who', 'A', '非限制性、后接名词 verse 表所属 → whose。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.03'), '____ we all know, a good poem should be read aloud and with feeling.', 'Which', 'As', 'That', 'What', 'B', 'as 引导非限制性从句表「正如」,常置句首 → As we all know。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.03'), 'My favourite poet is Milne, ____ wrote the gentle poem ''Wind on the Hill''.', 'that', 'which', 'who', 'whom', 'C', '非限制性、指人作主语 → who。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U5' AND code='e3u5.03'), 'The class voted for her poem, ____ was clearly the best of them all.', 'that', 'what', 'where', 'which', 'D', '非限制性、指物(her poem)作主语 → which。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'Where Poetry Began', 'Poetry probably had its origins in traditional folk music tens of thousands of years ago. In that distant age, there were no books or films, and writing had not yet been invented. So at night people would sit around the fire and sing songs to entertain themselves. These songs reflected the daily lives of ordinary people, such as hunting animals or sowing crops in the fields. Because nothing was written down, the songs were passed on by mouth, and over the years different variations developed. Each area slowly grew its own special rhythm. People also liked to tell stories of past heroes. As these stories were often quite long, they were given rhyme and rhythm so that they could be remembered more easily. In the beginning such songs and stories were very simple, but over time they became more complicated and more polished. They were no longer the work of people sitting around a fire, but of true poets who cared deeply about their art.', 'Poems', 165, '[{"q":"According to the text, where did poetry most likely come from?","answer":"A","options":["From early folk songs sung long ago.","From printed books and films.","From written records of kings.","From schools that taught writing."],"explanation":"原文 ''Poetry probably had its origins in traditional folk music'' 的转述;其余与原文矛盾。"},{"q":"Why were rhyme and rhythm added to the long hero stories?","answer":"B","options":["To make them sound foreign.","To make them easier to remember.","To make them shorter.","To stop people singing them."],"explanation":"原文 ''they were given rhyme and rhythm so that they could be remembered more easily'' 的转述。"},{"q":"How did the songs change over a long time?","answer":"A","options":["They grew richer and more polished.","They disappeared completely.","They stayed exactly the same.","They were all written down at once."],"explanation":"原文 ''over time they became more complicated and more polished'' 的转述。"}]'::jsonb, '[{"word":"folk","cn":"民间的"},{"word":"variation","cn":"变体"},{"word":"sow","cn":"播种"}]'::jsonb, 2, 'elective3', 'U5');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'Short Forms of Poetry', 'Not every poem has to be long. One simple form that amateurs can easily write is the cinquain, which is made up of five lines. With just a few words, a cinquain can give a strong picture or create a certain mood. Another short form is the haiku, a Japanese kind of poetry that consists of seventeen syllables. It has a format of three lines, containing five, seven and five syllables respectively. The haiku is not a traditional English form, yet it is very popular with English writers. Like the cinquain, it can paint a clear picture and create a special feeling using very few words. Many haiku describe a single moment in nature, such as a fallen blossom drifting back towards the branch, or a delicate butterfly resting in the sun. These tiny poems remind us that a powerful feeling does not always need many lines. Sometimes a handful of well-chosen words can say more than a whole page of writing.', 'Poems', 162, '[{"q":"What is true about a cinquain?","answer":"B","options":["It must always be very long.","It is built out of five lines.","It has seventeen syllables.","Only experts can write one."],"explanation":"原文 ''the cinquain, which is made up of five lines'' 的转述。"},{"q":"How are the syllables arranged in a haiku?","answer":"C","options":["Seven in every line.","In no fixed number at all.","Five, seven and five across three lines.","Fourteen lines of equal length."],"explanation":"原文 ''three lines, containing five, seven and five syllables respectively'' 的转述。"},{"q":"What main point does the writer make about these short poems?","answer":"D","options":["They are too hard to understand.","They are only written in Japan.","They cannot describe nature.","Few words can still carry strong feeling."],"explanation":"原文 ''a powerful feeling does not always need many lines… a handful of well-chosen words can say more'' 的转述。"}]'::jsonb, '[{"word":"cinquain","cn":"五行诗"},{"word":"haiku","cn":"俳句"},{"word":"syllable","cn":"音节"}]'::jsonb, 2, 'elective3', 'U5');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'Tang Poems in English', 'English speakers also enjoy poems from China, and those from the Tang Dynasty are especially loved. A great deal of Tang poetry has been translated into English, so that readers all over the world can share its beauty. One well-known poem by Wang Jian tells of a faithful wife who waits for her husband on a mountain top. Day by day she stands there while the river flows on below and the wind and rain revolve around her. She never looks back, and at last she is turned into stone. The poem says that, should the traveller ever return, the stone would utter speech. In so few lines, the poet paints a picture of deep love and patient waiting. When such a poem is carried into another language, the translator must keep both its meaning and its music. That is not easy, yet a good English version allows new readers to feel the same quiet sorrow that Chinese readers have felt for over a thousand years.', 'Poems', 166, '[{"q":"What does the wife in Wang Jian''s poem do?","answer":"A","options":["She waits faithfully for her husband to come back.","She travels far away from home.","She forgets about her husband.","She breaks the stone on the hill."],"explanation":"原文 ''a faithful wife who waits for her husband'' 的转述。"},{"q":"What finally happens to the waiting wife?","answer":"B","options":["She returns to the city.","She becomes a stone on the mountain top.","She meets the traveller.","She sails down the river."],"explanation":"原文 ''at last she is turned into stone'' 的转述。"},{"q":"According to the writer, what must a translator keep?","answer":"C","options":["Only the length of the poem.","Only the name of the poet.","Both the meaning and the music of the poem.","Nothing of the original at all."],"explanation":"原文 ''the translator must keep both its meaning and its music'' 的转述。"}]'::jsonb, '[{"word":"await","cn":"等候"},{"word":"revolve","cn":"环绕旋转"},{"word":"utter","cn":"出声说"}]'::jsonb, 2, 'elective3', 'U5');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'The Browning Love Story', 'If you study the history of English literature, you will soon meet Robert and Elizabeth Barrett Browning. They were one of the most romantic literary couples of the Victorian era. Elizabeth began to write poetry at about the age of six, and in 1844 her Poems brought her great success. The book also caught the eye of the poet Robert Browning, who fell in love with her verse and then with the writer herself. The two began to exchange letters, and this warm correspondence sowed the seeds of love between them. Elizabeth had been ill for years and rarely saw visitors, yet Robert found a way to meet her. Her father was a dominant and selfish man who refused to let his daughter go, so the couple married in secret and moved to Italy in 1846. There Elizabeth spent the rest of her life, and Robert had a great influence on her writing. The finest proof of this is the famous collection Sonnets from the Portuguese.', 'Poems', 166, '[{"q":"What first attracted Robert Browning to Elizabeth?","answer":"D","options":["Her wealth and large house.","Her father''s social position.","Her plan to move to Italy.","Her poetry, which he greatly admired."],"explanation":"原文 ''fell in love with her verse and then with the writer herself'' 的转述。"},{"q":"Why did the couple marry in secret?","answer":"A","options":["Because her father would not allow it.","Because they had no money at all.","Because Robert lived in Italy.","Because Elizabeth disliked weddings."],"explanation":"原文 ''Her father was a dominant and selfish man who refused to let his daughter go'' 的转述。"},{"q":"What does the writer give as proof of Robert''s influence?","answer":"B","options":["A book of letters to her father.","His famous love poems known as Sonnets from the Portuguese.","A list of her early illnesses.","A diary kept in England."],"explanation":"原文 ''The finest proof of this is the famous collection Sonnets from the Portuguese'' 的转述。"}]'::jsonb, '[{"word":"literary","cn":"文学的"},{"word":"correspondence","cn":"通信"},{"word":"dominant","cn":"专横的"}]'::jsonb, 2, 'elective3', 'U5');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'How to Read a Poem', 'Poems paint pictures with words through figures of speech and metaphors. So to understand a poem fully, you have to imagine in your mind the very picture that the poem is painting. Start by reading the poem slowly and looking for its main image. Ask yourself what feeling the poet is trying to share, and whether the mood is happy, sad or calm. The sounds, rhythm and rhymes of a poem also give it a kind of musical quality, so a poem should almost always be read aloud. When you read aloud, find the rhythm of the words and let your voice follow it. Begin to think about how the poem makes you feel, and read it with that emotion, pouring out your feelings. Do not worry if you meet a new word; often the picture and the sound will help you guess its meaning. Read the poem more than once, for each reading usually brings something new that you missed before.', 'Poems', 162, '[{"q":"What does the writer say you must do to understand a poem fully?","answer":"C","options":["Count all the words on the page.","Translate it into another language first.","Picture the scene the poem describes in your mind.","Read only its title."],"explanation":"原文 ''imagine in your mind the very picture that the poem is painting'' 的转述。"},{"q":"Why should a poem usually be read aloud?","answer":"D","options":["To make it shorter.","To hide its meaning.","Because reading silently is forbidden.","Because its sound and rhythm give it a musical quality."],"explanation":"原文 ''sounds, rhythm and rhymes… give it a kind of musical quality, so a poem should almost always be read aloud'' 的转述。"},{"q":"What does the writer suggest doing when you meet a new word?","answer":"A","options":["Use the picture and sound to guess its meaning.","Stop reading at once.","Skip the whole poem.","Look only at the last line."],"explanation":"原文 ''often the picture and the sound will help you guess its meaning'' 的转述。"}]'::jsonb, '[{"word":"imagery","cn":"意象"},{"word":"rhythm","cn":"节奏"},{"word":"recite","cn":"吟诵"}]'::jsonb, 2, 'elective3', 'U5');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'Langston Hughes and His Dream', 'Langston Hughes was a famous African-American poet whose poems mainly tell the story of black people in America, including their joys and their pain. One of his most celebrated poems is called Dream Variation. It is about the dream of a world that is free of inequality and racial prejudice. In another short poem, simply named Dream, he tells readers to hold fast to their dreams. He warns that if dreams die, life becomes a broken-winged bird that cannot fly, and if dreams go, life turns into a barren field frozen with snow. Although the poem has only eight lines, its images stay in the mind for a long time. Hughes also helped to make free verse popular. A free verse poem does not follow any fixed rules; it has no regular metre or rhythm, so the poet has complete control over the creation. Through his simple but powerful words, Hughes gives his readers both comfort and hope.', 'Poems', 158, '[{"q":"What do most of Langston Hughes''s poems describe?","answer":"B","options":["The history of ancient China.","The lives, joys and pain of black Americans.","The rules of Japanese haiku.","His travels around Europe."],"explanation":"原文 ''tell the story of black people in America, including their joys and their pain'' 的转述。"},{"q":"What does the poem Dream tell readers to do?","answer":"C","options":["Forget their dreams quickly.","Stop writing poetry.","Hold tightly to their dreams.","Sleep more each night."],"explanation":"原文 ''he tells readers to hold fast to their dreams'' 的转述。"},{"q":"What is special about free verse, according to the text?","answer":"D","options":["It must rhyme on every line.","It always has seventeen syllables.","It can only be written in Japan.","It follows no fixed rules of metre or rhythm."],"explanation":"原文 ''A free verse poem does not follow any fixed rules; it has no regular metre or rhythm'' 的转述。"}]'::jsonb, '[{"word":"racial","cn":"种族的"},{"word":"prejudice","cn":"偏见"},{"word":"barren","cn":"贫瘠的"}]'::jsonb, 2, 'elective3', 'U5');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective3', 'U5', 'My First Poem', 'Last term our teacher asked each of us to (1)____ a short poem of our own. At first I thought it would be (2)____, because I was only an amateur and had never tried before. She told me to start with a (3)____ that mattered to me, and then to make a list of the words I wanted to (4)____. I chose my little brother, who is always (5)____ me and laughing. Slowly the lines came together, and I felt a quiet (6)____ of joy. When I read the poem (7)____, I could hear that two of the lines (8)____ nicely. My teacher said the (9)____ of the words sounded just like a song. That was the day (10)____ I first fell in love with writing poetry.', 127, 2, '[{"q":"1","answer":"A","options":["write","eat","sell","throw"],"explanation":"write a poem 写诗;其余动词不搭。"},{"q":"2","answer":"B","options":["delicious","difficult","tasty","sunny"],"explanation":"thought it would be difficult 觉得会很难。"},{"q":"3","answer":"C","options":["price","ticket","theme","machine"],"explanation":"start with a theme 从主题开始。"},{"q":"4","answer":"D","options":["drop","lose","hide","use"],"explanation":"words I wanted to use 想用的词。"},{"q":"5","answer":"A","options":["teasing","selling","buying","cooking"],"explanation":"always teasing me 总是逗弄我。"},{"q":"6","answer":"B","options":["noise","feeling","price","weather"],"explanation":"a feeling of joy 一种喜悦之情。"},{"q":"7","answer":"C","options":["alone","asleep","aloud","afraid"],"explanation":"read the poem aloud 大声朗读。"},{"q":"8","answer":"D","options":["broke","ate","left","rhymed"],"explanation":"the lines rhymed 诗行押韵。"},{"q":"9","answer":"A","options":["rhythm","price","noise","machine"],"explanation":"the rhythm of the words 词语的节奏。"},{"q":"10","answer":"B","options":["where","when","why","whose"],"explanation":"the day when 时间先行词、从句完整 → when。"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective3', 'U5', 'A Lesson on the Haiku', 'Today our English class learned about a Japanese (1)____ called the haiku. Our teacher explained that it has just seventeen (2)____, set out in three short lines. The three lines hold five, seven and five sounds (3)____. Although it is very (4)____, a haiku can still paint a clear picture in the reader''s mind. She showed us one (5)____ about a fallen blossom drifting back towards its branch, and another about a (6)____ butterfly resting in the sun. With so (7)____ words, the poet still creates a special (8)____. We then tried to (9)____ our own haiku about the rain outside the window. It was harder than it looked, but by the end of the lesson everyone had (10)____ a tiny poem of their own.', 125, 2, '[{"q":"1","answer":"C","options":["price","machine","form","garden"],"explanation":"a Japanese form 一种日本诗体;同为名词。"},{"q":"2","answer":"D","options":["prices","tickets","machines","syllables"],"explanation":"seventeen syllables 十七个音节。"},{"q":"3","answer":"A","options":["respectively","loudly","slowly","angrily"],"explanation":"five, seven and five respectively 依次为。"},{"q":"4","answer":"B","options":["tall","short","heavy","wide"],"explanation":"very short 很短。"},{"q":"5","answer":"C","options":["song","price","haiku","shop"],"explanation":"showed us one haiku 给我们看一首俳句。"},{"q":"6","answer":"D","options":["heavy","loud","angry","delicate"],"explanation":"a delicate butterfly 一只脆弱的蝴蝶。"},{"q":"7","answer":"A","options":["few","many","loud","rich"],"explanation":"so few words 这么少的词。"},{"q":"8","answer":"B","options":["price","mood","noise","machine"],"explanation":"a special mood 一种特别的情绪。"},{"q":"9","answer":"C","options":["sell","lose","write","throw"],"explanation":"write our own haiku 写自己的俳句。"},{"q":"10","answer":"D","options":["bought","lost","sold","created"],"explanation":"had created a tiny poem 创作了一首小诗。"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective3', 'U5', 'The Poetry Evening', 'Every spring our school holds a poetry evening (1)____ students read their favourite poems aloud. This year I chose a poem (2)____ I had loved since I was a child. Before the show, I practised many times so that I could (3)____ every line clearly and with feeling. My hands were shaking, for I am only an (4)____, not a real poet. But my teacher smiled and told me to find the (5)____ of the words and let my voice follow it. When my turn came, I took a deep breath and began to (6)____. To my surprise, the room fell silent, (7)____ made me feel proud. People said the poem''s gentle (8)____ moved them almost to tears. That evening I learned that a poem comes truly (9)____ only when it is read aloud. I will never forget the moment (10)____ the whole audience clapped for me.', 147, 2, '[{"q":"1","answer":"A","options":["where","which","who","whose"],"explanation":"the evening where 地点(场合)、从句完整 → where。"},{"q":"2","answer":"B","options":["who","that","where","when"],"explanation":"a poem that I had loved 指物缺宾语 → that。"},{"q":"3","answer":"C","options":["sell","throw","recite","lose"],"explanation":"recite every line 吟诵每一行。"},{"q":"4","answer":"D","options":["expert","engineer","doctor","amateur"],"explanation":"only an amateur 只是个业余爱好者。"},{"q":"5","answer":"A","options":["rhythm","price","machine","garden"],"explanation":"the rhythm of the words 词语的节奏。"},{"q":"6","answer":"B","options":["sleep","read","cook","buy"],"explanation":"began to read 开始朗读。"},{"q":"7","answer":"C","options":["that","what","which","where"],"explanation":"非限制性 which 指代前句 → which。"},{"q":"8","answer":"D","options":["price","noise","machine","mood"],"explanation":"the poem''s gentle mood 诗温柔的情绪。"},{"q":"9","answer":"A","options":["alive","asleep","afraid","angry"],"explanation":"comes alive 鲜活起来。"},{"q":"10","answer":"B","options":["where","when","why","whose"],"explanation":"the moment when 时间先行词、从句完整 → when。"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective3', 'U5', 'Reading a Poem Slowly', 'Many readers give up on poetry because they read it too (1)____. A poem is not like a story; it asks you to slow down and (2)____ each picture it paints. First, look for the main (3)____ that the poet places in your mind. Next, ask yourself what (4)____ the poet wants to share, whether it is happy or sad. The sounds and rhymes give a poem a musical (5)____, so it is best to read it (6)____. If you meet a word you do not know, do not (7)____; the picture and the sound often help you guess its meaning. Read the same poem more than (8)____, for each time usually brings something new. Little by little you will begin to (9)____ how beautiful a few simple lines can be. Then poetry will no longer feel (10)____ to you at all.', 142, 2, '[{"q":"1","answer":"C","options":["slowly","softly","fast","kindly"],"explanation":"read it too fast 读得太快。"},{"q":"2","answer":"D","options":["sell","lose","throw","imagine"],"explanation":"imagine each picture 想象每个画面。"},{"q":"3","answer":"A","options":["image","price","ticket","machine"],"explanation":"the main image 主要意象。"},{"q":"4","answer":"B","options":["price","feeling","noise","weather"],"explanation":"what feeling 什么感受。"},{"q":"5","answer":"C","options":["machine","garden","quality","ticket"],"explanation":"a musical quality 音乐般的特质。"},{"q":"6","answer":"D","options":["alone","asleep","afraid","aloud"],"explanation":"read it aloud 大声朗读。"},{"q":"7","answer":"A","options":["worry","sing","sell","cook"],"explanation":"do not worry 不要担心。"},{"q":"8","answer":"B","options":["never","once","nowhere","anyone"],"explanation":"more than once 不止一次。"},{"q":"9","answer":"C","options":["forget","lose","appreciate","sell"],"explanation":"appreciate how beautiful 欣赏其美。"},{"q":"10","answer":"D","options":["tasty","sunny","loud","strange"],"explanation":"feel strange 感到陌生。"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective3', 'U5', 'Entering the Poetry Contest', 'Our teacher told us about a poetry (1)____ that the city was holding for young writers. The (2)____ for sending in our work was the end of the month, so we had to hurry. Nora said she still needed time to (3)____ her writing, because her first lines did not yet sound right. Pitt did not want to (4)____ at all, for he thought his poems were too simple. But the teacher said that even an (5)____ can win if the feeling is true. George planned to (6)____ a poem about his grandmother, (7)____ had taught him many old songs. He chose his words with care so that the lines would (8)____ and flow like music. On the last day, he read his poem (9)____ to the class, and everyone clapped. He did not win first prize, but he felt proud of the (10)____ he had created.', 147, 2, '[{"q":"1","answer":"A","options":["contest","price","machine","garden"],"explanation":"a poetry contest 诗歌比赛。"},{"q":"2","answer":"B","options":["price","deadline","noise","ticket"],"explanation":"the deadline 截止日期。"},{"q":"3","answer":"C","options":["sell","throw","polish","lose"],"explanation":"polish her writing 润色作品。"},{"q":"4","answer":"D","options":["sleep","cook","drive","enter"],"explanation":"did not want to enter 不想参赛。"},{"q":"5","answer":"A","options":["amateur","engineer","doctor","driver"],"explanation":"even an amateur 即便业余爱好者。"},{"q":"6","answer":"B","options":["sell","write","lose","throw"],"explanation":"write a poem 写一首诗。"},{"q":"7","answer":"C","options":["which","where","who","when"],"explanation":"非限制性、指人(grandmother)作主语 → who。"},{"q":"8","answer":"D","options":["break","sell","sleep","rhyme"],"explanation":"the lines would rhyme 诗行押韵。"},{"q":"9","answer":"A","options":["aloud","alone","asleep","afraid"],"explanation":"read his poem aloud 大声朗读。"},{"q":"10","answer":"B","options":["machine","poem","garden","ticket"],"explanation":"the poem he had created 他创作的诗。"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective3', 'U5', 'From Songs to Poems', 'Long ago, before books or films existed, people made up simple songs about their daily (1)____. They sang about hunting in the forest or (2)____ crops in the fields. Because nothing was written down, the songs were passed on by (3)____, and over the years many (4)____ of them grew up. Each region slowly formed its own special (5)____ and tune. People also liked to tell long stories about past heroes, (6)____ they gave rhyme so that the words were easier to (7)____. At first these songs were very simple, but in time they became more (8)____ and more polished. They were no longer the work of villagers around a (9)____, but of true poets who cared deeply about their (10)____. In this way, music slowly turned into the poetry we know today.', 133, 2, '[{"q":"1","answer":"C","options":["prices","machines","lives","tickets"],"explanation":"daily lives 日常生活。"},{"q":"2","answer":"D","options":["selling","buying","cooking","sowing"],"explanation":"sowing crops 播种庄稼。"},{"q":"3","answer":"A","options":["mouth","price","machine","ticket"],"explanation":"passed on by mouth 口口相传。"},{"q":"4","answer":"B","options":["prices","variations","machines","tickets"],"explanation":"many variations 许多变体。"},{"q":"5","answer":"C","options":["price","machine","rhythm","garden"],"explanation":"its own special rhythm 自己的节奏。"},{"q":"6","answer":"D","options":["but","or","nor","so"],"explanation":"so they gave rhyme 因此加上押韵(表结果)。"},{"q":"7","answer":"A","options":["remember","sell","throw","lose"],"explanation":"easier to remember 更易记住。"},{"q":"8","answer":"B","options":["cheap","complicated","tasty","sunny"],"explanation":"more complicated 更复杂。"},{"q":"9","answer":"C","options":["price","machine","fire","ticket"],"explanation":"around a fire 围着火堆。"},{"q":"10","answer":"D","options":["machine","garden","ticket","art"],"explanation":"cared about their art 在意他们的艺术。"}]'::jsonb, 6);
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U5 听力·对话 The Poetry Contest', '选择性必修三 U5 · dialogue', 3, 'Teacher: Our city is holding a poetry contest. Would any of you like to enter?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U5 听力·短文 What Is a Haiku', '选择性必修三 U5 · passage', 2, 'A haiku is a short form of poetry that comes from Japan.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U5 听力·对话 Choosing a Poem', '选择性必修三 U5 · dialogue', 3, 'Mia: I have to read a poem aloud tomorrow, but I can''t decide which one.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U5 听力·短文 How to Read a Poem Aloud', '选择性必修三 U5 · passage', 2, 'Poetry should always be read aloud, for that is when you hear its music.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U5 听力·对话 Writing Our Own Poem', '选择性必修三 U5 · dialogue', 3, 'Tom: I want to write my own poem, but I don''t know how to start.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U5 听力·短文 The Beauty of Poems', '选择性必修三 U5 · passage', 2, 'Poems paint pictures with words, using images and comparisons.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit) VALUES (12, 'Write about a Favourite Poem(赏析一首你喜爱的诗)', 'My Favourite Poem', '请用英语写一篇约100词的短文,介绍并赏析你最喜爱的一首诗(可选 Dream / Wind on the Hill / 一首唐诗等)。内容包括:① 这首诗的名字、作者和大意;② 它的意象、押韵或节奏给你的感受;③ 你从中获得的启发,以及你为何喜爱它。注意尽量用上定语从句。', 'Write a short essay (about 100 words) introducing and appreciating your favourite poem (e.g. ''Dream'', ''Wind on the Hill'', or a Tang poem). Include: 1) the title, the poet and what the poem is about; 2) the images, rhyme or rhythm and how they make you feel; 3) the message it gives you and why you love it. Try to use relative clauses.', '["介绍诗名、作者与大意(The poem … , which was written by … , is about …)","赏析意象/押韵/节奏与感受(When I read it aloud, I can hear that … rhyme; I can picture …)","诗给你的启发与你喜爱的原因(The poet wants us to … , which is why I love this poem)","尽量使用定语从句、句句围绕这首诗"]'::jsonb, 70, 100, 'My favourite poem is ''Dream'', which was written by Langston Hughes. Although it has only eight short lines, it carries a deep feeling. The poem tells us to hold fast to our dreams, because a life without dreams is like a broken-winged bird that cannot fly. When I read it aloud, I can hear that ''die'' and ''fly'' rhyme, and the gentle rhythm sounds like quiet music. In my mind I can see a bird and a barren field frozen with snow. The poet, who spoke up for hope, wants us never to give up. That is the very reason why I love this poem.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["My favourite poem is ''Dream'', which was written by Langston Hughes.","Although it has only eight short lines, it carries a deep feeling.","When I read it aloud, I can hear that ''die'' and ''fly'' rhyme.","The poet, who spoke up for hope, wants us never to give up."]'::jsonb, '[{"wrong":"The poem who I love most is ''Dream''.","correct":"The poem that I love most is ''Dream''.","note":"先行词 poem 指物,应用 that/which,不用 who。"},{"wrong":"It tells us holding fast to our dreams.","correct":"It tells us to hold fast to our dreams.","note":"tell sb to do sth 用不定式。"},{"wrong":"The reason which I love it is its rhythm.","correct":"The reason why I love it is its rhythm.","note":"先行词 reason、从句缺原因状语,用 why(或 that/for which)。"}]'::jsonb, '【诗歌赏析结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content) VALUES (12, 'elective3', 'U5', '{"title":"定语从句复习·关系词速查","intro":"定语从句修饰先行词。判断口诀:先看先行词指人还是指物,再看从句缺什么成分——缺主语/宾语用关系代词(who/whom/which/that),不缺主宾只缺状语用关系副词(where/when/why)或「介词+which」;表所属用 whose。非限制性(有逗号)绝不用 that。","table":{"headers":["关系词","用法 / 例句"],"rows":[["who","指人、作主语:the poet who wrote this sonnet"],["whom","指人、作宾语(或介词后):the man whom she married / to whom"],["which","指物;非限制性指物;指代整句:a poem which… / …, which made me cry"],["that","指人/物、限从、缺主宾:the poem that I love(非限从绝不用)"],["whose","表所属、后接名词:the poet whose poems we love"],["where/when/why","缺状语:the place where / the year when / the reason why"],["介词+which/whom","正式或介词提前:in which / by which / to whom"]]},"specialRules":[{"rule":"从句缺主语/宾语 → 关系代词(who/whom/which/that)","mark":"the poem that I love(缺宾语→that)"},{"rule":"从句不缺主宾、只缺状语 → 关系副词或介词+which","mark":"the room where we met = in which we met"},{"rule":"非限制性(逗号)指人用 who、指物用 which,绝不用 that","mark":"Tagore, who… √ / Tagore, that… ×"},{"rule":"which 可指代前面整个句子;as 引导非限从表「正如」可置句首","mark":"…, which surprised us / As is known, …"},{"rule":"介词后只能用 which / whom,不可用 that","mark":"by which √ / by that ×"}],"why":["关系代词在从句里充当主语或宾语,所以从句会缺一个主宾成分;关系副词(=介词+which)在从句里充当状语,从句主宾都不缺。先数从句缺什么,关系词就选好了。"],"gaokaoPoints":["who/whom/which/that/whose 与 where/when/why 的判断(看从句缺主宾还是缺状语);语法填空与短文改错高频。","非限制性从句:指人 who、指物 which、绝不用 that;which 指代整句;as 引导(as is known/as we all know)。"],"examVsReal":[{"exam":"the house in which I live(考试/书面)","real":"the house I live in","note":"考试常用「介词+which」;口语里关系词常省略、把介词放句末。"},{"exam":"the reason why he left(考试)","real":"the reason he left","note":"考试用 why;口语里 why 常被省略或用 that。"}]}'::jsonb);
